import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.CqdVOxXJ.js";const o="/rakkii-cars-guide/screenshots/v2/d08-finance-cash.png",r="/rakkii-cars-guide/screenshots/v2/d10-who-owes-us.png",i="/rakkii-cars-guide/screenshots/v2/d05-parts-inventory.png",h="/rakkii-cars-guide/screenshots/v2/d17-hr-payroll.png",p="/rakkii-cars-guide/screenshots/v2/d22-staff-and-pay.png",c="/rakkii-cars-guide/screenshots/v2/d21-shop-settings.png",v=JSON.parse('{"title":"Running the shop","description":"","frontmatter":{},"headers":[],"relativePath":"desk/running-the-shop.md","filePath":"desk/running-the-shop.md","lastUpdated":1794643263000}'),l={name:"desk/running-the-shop.md"};function d(g,e,u,m,f,y){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="running-the-shop" tabindex="-1">Running the shop <a class="header-anchor" href="#running-the-shop" aria-label="Permalink to &quot;Running the shop&quot;">​</a></h1><p><strong>Who:</strong> Owner (some pages admin too) · <strong>Hubs:</strong> Workshop, Finance, HR, Admin</p><p>The regular jobs that aren&#39;t about one car. Each section says where to go and what to do; the reference pages have the full rules.</p><h2 id="every-day" tabindex="-1">Every day <a class="header-anchor" href="#every-day" aria-label="Permalink to &quot;Every day&quot;">​</a></h2><h3 id="check-the-cash" tabindex="-1">Check the cash <a class="header-anchor" href="#check-the-cash" aria-label="Permalink to &quot;Check the cash&quot;">​</a></h3><p><strong>Finance › Cash</strong> shows <strong>Today</strong> (money in and out), <strong>Open AR</strong> (what customers and insurers owe) and <strong>Payables due (7d)</strong>.</p><p><img src="'+o+'" alt="Finance Cash"></p><h3 id="review-payment-proofs" tabindex="-1">Review payment proofs <a class="header-anchor" href="#review-payment-proofs" aria-label="Permalink to &quot;Review payment proofs&quot;">​</a></h3><p><strong>Finance › Payments › Pending proofs</strong> lists GCash and Maya screenshots sent from customers&#39; pay links. Check the money arrived, then confirm or reject each one.</p><h3 id="record-expenses" tabindex="-1">Record expenses <a class="header-anchor" href="#record-expenses" aria-label="Permalink to &quot;Record expenses&quot;">​</a></h3><p><strong>Finance › Expenses › Add expense</strong> for shop costs that aren&#39;t parts for a job (rent, utilities, supplies).</p><h3 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to &quot;Attendance&quot;">​</a></h3><p><strong>HR › Attendance</strong> shows everyone&#39;s punches. Approve or reject off-site punches and overtime under <strong>OT to approve</strong>. Forgot to clock someone? Use <strong>Punch for…</strong>.</p><p>The <strong>Clock kiosk</strong> (<strong>HR › Clock kiosk</strong>) turns a shop tablet into a time clock: staff tap their name.</p><h2 id="every-week" tabindex="-1">Every week <a class="header-anchor" href="#every-week" aria-label="Permalink to &quot;Every week&quot;">​</a></h2><h3 id="who-owes-us" tabindex="-1">Who owes us <a class="header-anchor" href="#who-owes-us" aria-label="Permalink to &quot;Who owes us&quot;">​</a></h3><p><strong>Finance › Who owes us</strong> lists every unpaid customer and insurer balance, with its age and expected date. Follow up on the oldest first. Details: <a href="/rakkii-cars-guide/reference/08-lane-4-billing-chain-receivables-storage-credit-notes">Billing, receivables &amp; credit notes</a>.</p><p><img src="'+r+'" alt="Who owes us"></p><h3 id="pay-suppliers" tabindex="-1">Pay suppliers <a class="header-anchor" href="#pay-suppliers" aria-label="Permalink to &quot;Pay suppliers&quot;">​</a></h3><p><strong>Finance › Payables</strong> groups supplier bills into <strong>Due soon</strong>, <strong>Overdue</strong>, <strong>Open</strong> and <strong>Paid</strong>. Press <strong>Pay</strong> to record a payment.</p><h3 id="parts-stock" tabindex="-1">Parts stock <a class="header-anchor" href="#parts-stock" aria-label="Permalink to &quot;Parts stock&quot;">​</a></h3><p><strong>Workshop › Parts &amp; Inventory</strong> shows stock, <strong>Low stock</strong> and the value on hand. Use <strong>Receive</strong> when parts arrive and <strong>Restock POs</strong> to reorder. Details: <a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">Parts, canvass &amp; payables</a>.</p><p><img src="'+i+'" alt="Parts &amp; Inventory"></p><h3 id="leave-requests" tabindex="-1">Leave requests <a class="header-anchor" href="#leave-requests" aria-label="Permalink to &quot;Leave requests&quot;">​</a></h3><p><strong>HR › Leave approvals</strong>: decide the requests under <strong>Needs a decision</strong>. When you approve, the app lists the person&#39;s open jobs so you can hand them to someone else.</p><h2 id="every-pay-period" tabindex="-1">Every pay period <a class="header-anchor" href="#every-pay-period" aria-label="Permalink to &quot;Every pay period&quot;">​</a></h2><h3 id="run-payroll" tabindex="-1">Run payroll <a class="header-anchor" href="#run-payroll" aria-label="Permalink to &quot;Run payroll&quot;">​</a></h3><ol><li>Open <strong>HR › Payroll</strong> and choose the period (<strong>Semi-monthly (½)</strong> or <strong>Full month</strong>).</li><li>Check each person&#39;s hours, amount, deductions and net. Fix open punches and overtime first in <strong>HR › Attendance</strong>.</li><li>Press <strong>Save</strong>, then <strong>Lock period</strong> when it&#39;s final. Payslips appear in each person&#39;s <strong>Me › My payslip</strong>.</li></ol><p><img src="'+h+'" alt="Payroll"></p><p>Details: <a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">HR, payroll &amp; documents</a>.</p><h2 id="every-month" tabindex="-1">Every month <a class="header-anchor" href="#every-month" aria-label="Permalink to &quot;Every month&quot;">​</a></h2><h3 id="reports-and-p-l" tabindex="-1">Reports and P&amp;L <a class="header-anchor" href="#reports-and-p-l" aria-label="Permalink to &quot;Reports and P&amp;L&quot;">​</a></h3><ul><li><strong>Finance › Reports</strong>: sales by job type and payer, top accounts and what&#39;s owed, for <strong>This month</strong>, <strong>Last month</strong>, <strong>This quarter</strong> or a custom range.</li><li><strong>Finance › Job P&amp;L</strong>: the <strong>Monthly shop P&amp;L</strong> (revenue, costs, net profit) and the profit on each job.</li></ul><h3 id="close-the-month" tabindex="-1">Close the month <a class="header-anchor" href="#close-the-month" aria-label="Permalink to &quot;Close the month&quot;">​</a></h3><p><strong>Finance › Month close</strong> (owner only). When a month shows <strong>Ready to close</strong>, press <strong>Close month</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Closing is final</p><p>After a month is closed, money in that month can&#39;t be changed. Corrections go into the current month. Close only after every payment, expense and invoice for the month is in.</p></div><p>Details: <a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Finance &amp; month close</a>.</p><h2 id="now-and-then" tabindex="-1">Now and then <a class="header-anchor" href="#now-and-then" aria-label="Permalink to &quot;Now and then&quot;">​</a></h2><h3 id="announcements" tabindex="-1">Announcements <a class="header-anchor" href="#announcements" aria-label="Permalink to &quot;Announcements&quot;">​</a></h3><p><strong>HR › Announcements › New announcement</strong> posts a message at the top of everyone&#39;s home page.</p><h3 id="staff-and-access" tabindex="-1">Staff and access <a class="header-anchor" href="#staff-and-access" aria-label="Permalink to &quot;Staff and access&quot;">​</a></h3><p><strong>Admin › Staff and pay</strong> lists everyone with their access and pay. Access switches include <strong>Canvass &amp; pay</strong>, <strong>LOA files</strong>, <strong>LOA amounts</strong> and <strong>Time clock</strong>. Add a new person in <strong>HR › Directory</strong> first.</p><p><img src="'+p+'" alt="Staff and pay"></p><h3 id="shop-settings" tabindex="-1">Shop settings <a class="header-anchor" href="#shop-settings" aria-label="Permalink to &quot;Shop settings&quot;">​</a></h3><p><strong>Admin › Shop settings</strong> holds the shop&#39;s rules, grouped as <strong>Getting paid</strong>, <strong>Workshop rules</strong>, <strong>Buying</strong>, <strong>Sales &amp; commission</strong>, <strong>Staff &amp; time</strong>, <strong>Customer site</strong> and <strong>Advanced</strong>. For example, down payments and release holds are under <strong>Getting paid</strong>. Press <strong>Edit</strong> on a card to change it.</p><p><img src="'+c+'" alt="Shop settings, Getting paid"></p><p>Details: <a href="/rakkii-cars-guide/reference/13-admin-shop-settings-and-staff-permissions">Shop settings &amp; staff</a>.</p>',47)])])}const b=s(l,[["render",d]]);export{v as __pageData,b as default};
